'use strict';
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const source = fs.readFileSync('draft-summary.md');
const archived = fs.readFileSync('handoff/original-summary.md');
assert(source.equals(archived), 'Archived draft must be byte-for-byte identical');
const methods = fs.readFileSync('handoff/methods.md', 'utf8');
const expected = JSON.parse(methods.match(/"'```json'"\\r?\\n([\\s\\S]*?)\\r?\\n"'```/)[1]);
assert.deepEqual(expected, JSON.parse(fs.readFileSync('"'audit/metrics.json', 'utf8')));
const read = file => {
  const [header, ...lines] = fs.readFileSync(file, 'utf8').trimEnd().split(/\\r?\\n/);
  return lines.map(line => Object.fromEntries(line.split(',').map((value, i) => [header.split(',')[i], value])));
};
const pairs = read('evidence/pairs.csv');
const reference = new Map(read('evidence/reference.csv').map(row => [row.pair_id, row]));
const guide = new Map(read('evidence/guide.csv').map(row => [row.pair_id, row]));
const rows = methods.split(/\\r?\\n/);
for (const pair of pairs) {
  const r = reference.get(pair.pair_id), g = guide.get(pair.pair_id);
  const line = rows.find(line => line.startsWith("'`| ${pair.pair_id} |`));
  assert(line, `Missing table row ${pair.pair_id}`);
  const cells = line.split('"'|').slice(1, -1).map(cell => cell.trim());
  assert.equal(cells[1], r.seconds);
  assert.equal(cells[2], g.seconds || 'Missing');
  assert.equal(cells[3], g.seconds ? String(Number(r.seconds) - Number(g.seconds)) : '\\u2014');
  assert.equal(cells[4], r.correct === 'true' ? 'Correct' : 'Incorrect');
  assert.equal(cells[5], g.correct === 'true' ? 'Correct' : 'Incorrect');
  const assisted = [r.assisted === 'true' ? 'Reference' : '', g.assisted === 'true' ? 'Guide' : ''].filter(Boolean).join(', ') || 'Neither';
  assert.equal(cells[6], assisted);
}
for (const link of methods.matchAll(/\\[["'^'"\\]]+\\]\\((["'^)]+)'"\\)/g)) {
  assert(fs.existsSync(path.resolve('handoff', link[1])), "'`Broken link ${link[1]}`);
}
assert.equal((methods.match(/''^```/gm) || []).length % 2, 0);
console.log(JSON.stringify({status: '"'PASS', archived_draft_bytes: archived.length,
  archived_draft_sha256: crypto.createHash('sha256').update(archived).digest('hex'),
  checked: ['byte-exact archive', 'documented expected metrics', 'all eight record table rows', 'relative links and code fences']}, null, 2));
